-- load_employee_staging.sql
-- Generated by scripts/make_wwi_jobs.py: edit WWI_JOBS there and rerun it, rather than editing this file.
-- Fills WideWorldImportersDW.Integration.Employee_Staging the way Microsoft's SSIS package would,
-- so Integration.MigrateStagedEmployeeData has input to work on.
-- Run against WideWorldImportersDW. Needs the WideWorldImporters (shop) database on the same server.

SET NOCOUNT ON;

-- 1. Pick a time window: @WindowMonths long, ending @MonthsBack months before the warehouse's last load.
--    The default is the dev batch; jobs/employee.json changes it for the holdout.
DECLARE @MonthsBack   int = 0;
DECLARE @WindowMonths int = 1;
DECLARE @LastLoad   datetime2(7) = (SELECT [Cutoff Time] FROM Integration.[ETL Cutoff] WHERE [Table Name] = N'Employee');
DECLARE @NewCutoff  datetime2(7) = DATEADD(month, -@MonthsBack, @LastLoad);
DECLARE @LastCutoff datetime2(7) = DATEADD(month, -@WindowMonths, @NewCutoff);

-- 2. Clear staging (in-memory tables don't allow TRUNCATE)
DELETE FROM Integration.Employee_Staging;

-- 3. Pull the rows from the shop database. In-memory tables can't be written in the same
--    statement as another user database, so go through a temp table.
CREATE TABLE #rows (
    [WWI Employee ID] int,
    [Employee] nvarchar(50),
    [Preferred Name] nvarchar(50),
    [Is Salesperson] bit,
    [Photo] varbinary(max),
    [Valid From] datetime2(7),
    [Valid To] datetime2(7)
);

INSERT INTO #rows
EXEC WideWorldImporters.Integration.GetEmployeeUpdates @LastCutoff = @LastCutoff, @NewCutoff = @NewCutoff;

INSERT INTO Integration.Employee_Staging ([WWI Employee ID], [Employee], [Preferred Name], [Is Salesperson], [Photo], [Valid From], [Valid To])
SELECT [WWI Employee ID], [Employee], [Preferred Name], [Is Salesperson], [Photo], [Valid From], [Valid To]
FROM #rows;

DROP TABLE #rows;

-- 4. Open a lineage record. MigrateStagedEmployeeData looks for one with no completion time.
EXEC Integration.GetLineageKey @TableName = N'Employee', @NewCutoffTime = @NewCutoff;

-- 5. Report what got staged
SELECT COUNT(*) AS staged_rows, @LastCutoff AS window_from, @NewCutoff AS window_to
FROM Integration.Employee_Staging;
